import{z as s,x as l,o as e,c as d,q as r,j as i,D as E,d as t,s as n,S as o,b as A}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"宏观策略的回测难点与收束","description":"","frontmatter":{"title":"宏观策略的回测难点与收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mac-backtest-map.md","filePath":"quant/mac-backtest-map.md","lastUpdated":1791413859000}'),p={name:"quant/mac-backtest-map.md"};function m(c,a,h,f,u,D){const B=l("Mermaid");return e(),d("div",null,[a[2]||(a[2]=r('<h1 id="宏观策略的回测难点与收束" tabindex="-1">宏观策略的回测难点与收束 <a class="header-anchor" href="#宏观策略的回测难点与收束" aria-label="Permalink to &quot;宏观策略的回测难点与收束&quot;">​</a></h1><div class="epigraph"><p>宏观回测最大的敌人不是拟合不足，而是叙事的事后可得性：每一条样本外失败的策略，在样本内都有一条看起来必然的故事线。</p><footer>—— 据 Leamer, American Economic Review, 1983 与 White, Econometrica, 2000 整理</footer></div><p><a href="/quant/mac-commodity-macro">上一课</a>把商品写成宏观轴与库存轴的两层状态，利率、外汇、商品三个表达账户至此写全。本课回到第一课埋下的承诺——「回测与实盘只能用实时口径」，把宏观回测特有的骗术列成协议，再对整门课收束。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一套宏观策略，回测与实盘的落差比高频策略大得多，原因四件套。第一，数据被改写：宏观序列逐轮修订，初值噪声大、修订后的序列平滑、拐点清晰——用修订后数据回测，阈值规则的误报比实盘能看到的少得多。第二，发布滞后：环比数据公布滞后一到两个月，信号按数据所属期而不是可得期对齐，每一步都在用未来。第三，独立样本极少：状态以年计，三十年样本只含几个完整周期，有效样本数是周期数不是月数。第四，叙事无限供给：故事线不占数据文件，海选叙事等于把 \\(N\\) 藏起来。缺口是把这些变成回测前就必须满足的协议，而不是事后自觉。</p><p><span class="marginnote">「环比数据公布滞后一到两个月」举例：美国 9 月的 CPI 要到 10 月中才发布。若回测把 9 月的信号记在 9 月底并据此「成交」，等于提前两周偷看了数据——实盘在那个时点根本拿不到这条信息。</span></p><h3 id="协议清单" tabindex="-1">协议清单 <a class="header-anchor" href="#协议清单" aria-label="Permalink to &quot;协议清单&quot;">​</a></h3><p>数据层四件事：用 vintage 或首发值口径重算状态，信号与执行按可得期做 as-of 连接（<a href="/quant/point-in-time">时点数据</a>、<a href="/quant/look-ahead-bias">前视偏差</a>）；标准化与参数只用滚动或递归窗口；对识别迟滞做敏感性——状态确认滞后 \\(k\\) 月就晚 \\(k\\) 月动手，夏普掉多少进报告；按叙事数计 \\(N\\)，过<a href="/quant/backtest-overfitting">多重检验</a>与<a href="/quant/deflated-sharpe">紧缩夏普</a>的门槛再谈上线。</p><p><span class="marginnote">美国 2008 年四季度 GDP 年率首报为 \\(-3.8\\%\\)，其后修订到 \\(-8.4\\%\\) 附近：按终值识别「衰退格」比按首值早了不止一个季度。修订不是误差项，是与状态相关的信号成分。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>执行层协议同样显式：换格与翻仓的成本按第三课口径，在条件指数最紧的时点计冲击；EM 远期按 NDF 可执行价、商品按避开滚仓窗的成交假设计（前两课的边界进回测）。归因分四层：状态判断（概率对错）、映射（象限与赢家）、工具（carry 与基差）、执行（滑点），四层分开才能回答错在哪一环。最后是稳健性：换指标集、换窗口、换阈值带重跑，结论报分布而不是报冠军——冠军是 \\(N\\) 次试验的最大值统计量，报它等于报噪声的运气。</p><p><span class="marginnote">「冠军是 \\(N\\) 次试验的最大值统计量」白话版：让 100 只猴子各挑一个阈值回测，总有一只夏普 2.0——它代表的是试验次数，不是技术。所以结论要看换参数后结果的整张分布，而不是把最好的那一个挑出来汇报。</span></p>',12)),(e(),i(o,null,{default:E(()=>[n(B,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20VD%5B%22vintage%20%E6%95%B0%E6%8D%AE%E5%BA%93%22%5D%20--%3E%20AO%5B%22as-of%20%E4%BF%A1%E5%8F%B7%E5%BF%AB%E7%85%A7%22%5D%0A%20%20AO%20--%3E%20RS%5B%22%E5%AE%9E%E6%97%B6%E5%8F%A3%E5%BE%84%E7%8A%B6%E6%80%81%E8%AF%86%E5%88%AB%22%5D%0A%20%20RS%20--%3E%20EX%5B%22%E6%89%A7%E8%A1%8C%EF%BC%9A%E7%B4%A7%E6%97%B6%E7%82%B9%E6%88%90%E6%9C%AC%22%5D%0A%20%20EX%20--%3E%20AT%5B%22%E5%9B%9B%E5%B1%82%E5%BD%92%E5%9B%A0%22%5D%0A%20%20AT%20--%3E%20MT%5B%22%E5%A4%9A%E9%87%8D%E6%A3%80%E9%AA%8C%EF%BC%9A%E6%8C%89%E5%8F%99%E4%BA%8B%E8%AE%A1%20N%22%5D%0A%20%20MT%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20OK%5B%22%E4%B8%8A%E7%BA%BF%E8%A7%82%E5%AF%9F%22%5D%0A%20%20MT%20--%3E%7C%E6%8B%92%E7%BB%9D%7C%20AR%5B%22%E5%BD%92%E6%A1%A3%E8%B4%9F%E7%BB%93%E6%9E%9C%22%5D%0A%20%20RS%20--%3E%20SEN%5B%22%E8%BF%9F%E6%BB%9E%E6%95%8F%E6%84%9F%E6%80%A7%20k%20%E6%9C%88%22%5D%0A%20%20SEN%20--%3E%20MT%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[t("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,"修订为什么系统性抬高回测而不是无偏加噪：修订方向与后续确认的状态相关——衰退确认后数据被大幅下修，用修订序列回测等于让阈值规则提前看到衰退的确认，第一课「平滑概率偷未来」的错误在数据层重演。独立样本少为什么致命：月度 \\(t\\) 值按观测数算，但周期级参数——格序、反应函数、状态数——每个周期只提供一个独立样本，参数不确定度远大于 \\(t\\) 值所示。这就是宏观策略的统计验收必须与机制论证并列的原因：机制错了，统计再好也上不了线；机制立住了，样本外仍要以年计去等。",-1)),(e(),i(o,null,{default:E(()=>[n(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20R0%5B%22%E9%A6%96%E6%8A%A5%E5%88%9D%E5%80%BC%3A%20%E5%99%AA%E5%A3%B0%E5%A4%A7%22%5D%20--%3E%20R1%5B%22%E9%80%90%E8%BD%AE%E4%BF%AE%E8%AE%A2%3A%20%E8%B6%8A%E6%94%B9%E8%B6%8A%E5%B9%B3%E6%BB%91%22%5D%0A%20%20R1%20--%3E%20R2%5B%22%E7%BB%88%E5%80%BC%3A%20%E6%8B%90%E7%82%B9%E6%B8%85%E6%99%B0%22%5D%0A%20%20R2%20--%3E%20BT%5B%22%E7%94%A8%E7%BB%88%E5%80%BC%E5%9B%9E%E6%B5%8B%3A%20%E8%AF%AF%E6%8A%A5%E5%B0%91%E4%BF%A1%E5%8F%B7%E5%87%86%22%5D%0A%20%20R0%20--%3E%20LV%5B%22%E5%AE%9E%E7%9B%98%E5%8F%AA%E8%A7%81%E5%88%9D%E5%80%BC%22%5D%0A%20%20LV%20--%3E%20LP%5B%22%E5%AE%9E%E7%9B%98%E8%AF%AF%E6%8A%A5%E5%A4%9A%E4%BF%A1%E5%8F%B7%E8%BF%9F%22%5D%0A%20%20BT%20--%3E%20GAP%5B%22%E5%9B%9E%E6%B5%8B%E5%A4%8F%E6%99%AE%E7%B3%BB%E7%BB%9F%E6%80%A7%E8%99%9A%E9%AB%98%22%5D%0A%20%20LP%20--%3E%20GAP%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">「独立样本是周期数不是月数」可以想成掷硬币：连续 360 个月的数据，若中间 84 个月都属于同一次衰退，它们更像同一次掷硬币的余波。宏观状态以年计，参数置信度由「经历过几个完整周期」封顶，30 年数据可能只给了三四次有效抽样。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>协议本身不免费：vintage 库有缺口，历史初值未必完整保存；敏感性每做一轮就是新试验，要计回 \\(N\\)。低频策略的样本外验证以年计，负结果归档与快照冻结是唯一让组织记住教训的机制。也不因噎废食：按清单执行的宏观回测依然可行，只是置信度必然低于同样本量的日内策略，仓位尺寸与监控频率要按这个折扣定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>回测口径四件套：vintage 首发值、as-of 连接、滚动窗口、迟滞敏感性。</li><li>修订与状态相关，用修订后数据等于把衰退确认偷进信号——数据层的前视。</li><li>独立样本是周期数不是月数；叙事计入 \\(N\\)，过多重检验门槛再谈上线。</li><li>成本按紧时点计，归因分状态、映射、工具、执行四层。</li><li>全课程收束：识别给出概率，象限给出赢家，流动性给出开关，战术层定预算，利率、外汇、商品是三个表达账户，回测纪律是它们共同的门槛。</li><li>出处：Leamer, AER, 1983；White, Econometrica, 2000；时点口径见<a href="/quant/point-in-time">时点数据</a>，多重检验见<a href="/quant/backtest-overfitting">回测过拟合</a>与<a href="/quant/deflated-sharpe">紧缩夏普</a>。</li></ul>',5))])}const q=s(p,[["render",m]]);export{_ as __pageData,q as default};
